using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using Object=UnityEngine.Object;
namespace MassiveArmy.EditorTools {
 public static class PlanetWeatherMotionValidation {
  [Serializable]sealed class Report{public string status="PASS",error="",gpu,scope="Isolated GPU cloud density motion at saved orbital attitude, 2560x1440 pixel footprint, unchanged 24 ray steps. Paired frozen wind/noise, 96 locations, four approximately 6 m translations each. Not full-scene FPS/capacity acceptance.";public float pointCloudLimitJump,filteredCloudLimitJump;public float pointLodJump,filteredLodJump;public float pointP95,filteredP95,pointMaximum,filteredMaximum,pointMeanOpacity,filteredMeanOpacity;}
  [Serializable]sealed class Pair{public string before,after;}
  public static void BuildTraceClients(){PlanetWeatherDepthValidation.Run();PlanetFlightWeatherValidation.Run();SurvivalBuild.GraphicsProbeClient();SurvivalBuild.WeatherTraceClient();}
  public static void PreparePilotAndBuild(){
   var args=Environment.GetCommandLineArgs();string root=Path.GetFullPath(args[Array.IndexOf(args,"-weather-pilot-fixture")+1]);
   string allowed=Path.GetFullPath("TestResults/Multiplayer/Live")+Path.DirectorySeparatorChar;if(!root.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Pilot fixture escaped disposable Live saves");
   var saved=JsonUtility.FromJson<MassiveArmy.Planetary.PlanetShipSimulationSnapshot>(File.ReadAllText(args[Array.IndexOf(args,"-weather-motion-view")+1]));
   string path=Path.Combine(root,"industry.xml");var world=MassiveArmy.Industrial.IndustrialAuthority.Load(path);var ship=world.multiplayer.ships.Find(s=>s.owner==1);if(ship==null)throw new InvalidOperationException("Missing diagnostic owner ship");
   var point=saved.pose.position;var q=saved.pose.rotation;ship.pose.x=point.x;ship.pose.y=point.y;ship.pose.z=point.z;ship.rotationX=q.x;ship.rotationY=q.y;ship.rotationZ=q.z;ship.rotationW=q.w;ship.velocityX=saved.pose.linearVelocity.x;ship.velocityY=saved.pose.linearVelocity.y;ship.velocityZ=saved.pose.linearVelocity.z;ship.physics=JsonUtility.ToJson(saved);ship.landed=false;ship.autoFlight=false;ship.pilot=0;
   if(!ship.invitedActors.Contains(2))ship.invitedActors.Add(2);
   foreach(long id in new[]{1L,2L}){var player=world.multiplayer.players.Find(p=>p.actor==id);var feet=MassiveArmy.Industrial.SurvivalShipAuthority.SeatFeet(world.Ship(1),id==1?-1:0);if(id==1){feet.x+=1.8;feet.z-=2;}feet.body=ship.pose.body;feet.frame=ship.entity;player.interiorPose=feet;player.interiorWalking=true;player.attachedShip=ship.entity;player.controlledShip=player.controlledEntity=0;player.shipSeat=-1;player.oxygen=player.hunger=player.thirst=100;world.Actor(id).health=100;var offset=MassiveArmy.Planetary.Double3.Rotate(q,new MassiveArmy.Planetary.Double3(feet.x,feet.y,feet.z))+point;world.Actor(id).pose=new MassiveArmy.Industrial.FramePose{body=ship.pose.body,x=offset.x,y=offset.y,z=offset.z};}
   using(var authority=new MassiveArmy.Industrial.IndustrialAuthority(world,path))authority.Save();SurvivalBuild.GraphicsProbeClient();
  }
  static void PreparePair(){var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"-weather-fixture-pair");if(index<0)return;string pairPath=Path.GetFullPath(args[index+1]);var pair=JsonUtility.FromJson<Pair>(File.ReadAllText(pairPath));string allowed=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(pairPath),"Live"))+Path.DirectorySeparatorChar;
   foreach(string folder in new[]{pair.before,pair.after}){string root=Path.GetFullPath(folder);if(!root.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Orbit fixture escaped diagnostic Live root");string save=Path.Combine(root,"industry.xml");var world=MassiveArmy.Industrial.IndustrialAuthority.Load(save);
    foreach(var body in world.universe.bodies){var definition=ScriptableObject.CreateInstance<MassiveArmy.Planetary.PlanetDefinition>();try{JsonUtility.FromJsonOverwrite(body.json,definition);var surface=new MassiveArmy.Planetary.PlanetSurface(definition);foreach(var actor in world.actors){if(actor.pose.body!=body.body||actor.pose.frame!=0)continue;var point=surface.ProjectToSurface(new MassiveArmy.Planetary.Double3(actor.pose.x,actor.pose.y,actor.pose.z),.05);actor.pose=new MassiveArmy.Industrial.FramePose{body=body.body,x=point.x,y=point.y,z=point.z};actor.health=100;var player=world.multiplayer.players.Find(p=>p.actor==actor.id);if(player!=null){player.spawn=actor.pose;player.verticalSpeed=player.walkVelocityX=player.walkVelocityY=player.walkVelocityZ=0;player.oxygen=player.hunger=player.thirst=100;player.attachedShip=player.controlledShip=player.controlledEntity=0;player.interiorWalking=false;player.shipSeat=-1;}}}finally{Object.DestroyImmediate(definition);}}
    using(var authority=new MassiveArmy.Industrial.IndustrialAuthority(world,save))authority.Save();
   }
  }
  public static void ValidateAndBuild(){PreparePair();Run();if(!File.ReadAllText("TestResults/Planetary/WeatherMotion/result.json").Contains("\"status\": \"PASS\""))throw new InvalidOperationException("Weather motion checks failed");PlanetWeatherDepthValidation.Run();PlanetFlightWeatherValidation.Run();SurvivalBuild.PresentationClients();}
  public static void Run(){var report=new Report{gpu=SystemInfo.graphicsDeviceName};Material mat=null;Texture3D noise=null;Texture2D depth=null;RenderTexture light=null,trans=null,pixel=null;CommandBuffer cmd=null;
   try{
    var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"-weather-motion-view");if(index<0)throw new InvalidOperationException("Supply diagnostic saved orbit view");var saved=JsonUtility.FromJson<MassiveArmy.Planetary.PlanetShipSimulationSnapshot>(File.ReadAllText(args[index+1]));
    mat=new Material(Resources.Load<Shader>("MassiveArmy/PlanetWeather"));noise=new Texture3D(64,64,64,TextureFormat.R8,true){wrapMode=TextureWrapMode.Repeat,filterMode=FilterMode.Trilinear};uint Hash(uint v){v^=v>>16;v*=0x7feb352d;v^=v>>15;v*=0x846ca68b;return v^(v>>16);}var bytes=new byte[64*64*64];for(int i=0;i<bytes.Length;i++)bytes[i]=(byte)Hash((uint)i+8317);noise.SetPixelData(bytes,0);noise.Apply(true);depth=new Texture2D(2,2,TextureFormat.RFloat,false,true);depth.SetPixelData(new float[4],0);depth.Apply();
    RenderTexture RT(){var r=new RenderTexture(2560,1440,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);r.Create();return r;}light=RT();trans=RT();pixel=new RenderTexture(1,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);pixel.Create();cmd=new CommandBuffer{name="Paired cloud motion footprint"};
    mat.SetTexture("_WeatherNoise",noise);mat.SetTexture("_WeatherLocalDepth",depth);mat.SetTexture("_WeatherSceneDepth",depth);mat.SetVector("_WeatherFullSize",new Vector4(2560,1440,1f/2560,1f/1440));mat.SetVector("_WeatherHalfSize",new Vector4(2560,1440,1f/2560,1f/1440));mat.SetVector("_WeatherBounds",new Vector4(-1,-1,1,1));mat.SetVector("_WeatherView",new Vector4(16f/9,Mathf.Tan(30*Mathf.Deg2Rad),1,0));mat.SetFloat("_WeatherRadius",120000);mat.SetFloat("_WeatherPrecisionEnabled",1);mat.SetVector("_WeatherAtmosphere",new Vector4(.55f,.45f,22000f/120000,2872f/120000));mat.SetVector("_WeatherCloud",new Vector4(.439f,216,1,1));mat.SetVector("_WeatherCloudLod",new Vector4(24,3,0,0));mat.SetFloat("_WeatherNoiseSizeScale",.05f);mat.SetFloat("_WeatherNoiseFrequency",.31f);mat.SetVector("_WeatherOctaves",new Vector4(8,.1f,1.2f,0));mat.SetVector("_WeatherNoiseTuning",new Vector4(.916f,.3f,5.1f,.32f));mat.SetVector("_WeatherDetailMotion",new Vector4(0,1,.011f,1));uint seed=Hash(73129);float phase=5565.166f*25/120000;mat.SetVector("_WeatherWind",new Vector4(Mathf.Sin(phase),Mathf.Cos(phase),seed%997*.037f,(seed>>16)%991*.041f));mat.SetVector("_WeatherSun",new Vector3(.2f,1,-.3f).normalized);mat.SetVector("_WeatherSunColour",Vector3.one);mat.SetVector("_WeatherCloudColour",Vector3.one);mat.SetVector("_WeatherAirColour",new Vector3(.665f,.836f,1));mat.SetVector("_WeatherLightEffects",new Vector4(.65f,.475f,.6f,.894f));
    Color lastPixel=default;bool readNoise=false;float Draw(float angle){var q=Quaternion.AngleAxis(angle*Mathf.Rad2Deg,saved.lockNormal);var eye=MassiveArmy.Planetary.Double3.Rotate(q,saved.pose.position);var up=eye.Float.normalized;var attitude=Quaternion.LookRotation(Vector3.Cross(saved.lockNormal,up).normalized,up)*saved.lockOffset;mat.SetVector("_WeatherCentre",(eye*(-1.0/120000)).Float);mat.SetFloat("_WeatherEyeAltitude",(float)(eye.Magnitude/120000-1));mat.SetVector("_WeatherForward",attitude*Vector3.forward);mat.SetVector("_WeatherRight",attitude*Vector3.right);mat.SetVector("_WeatherUp",attitude*Vector3.up);cmd.Clear();cmd.SetRenderTarget(light);cmd.ClearRenderTarget(false,true,Color.clear);cmd.SetRenderTarget(trans);cmd.ClearRenderTarget(false,true,Color.white);cmd.SetRenderTarget(new[]{new RenderTargetIdentifier(light),new RenderTargetIdentifier(trans)},BuiltinRenderTextureType.None);cmd.DisableScissorRect();cmd.SetViewport(new Rect(0,0,2560,1440));cmd.EnableScissorRect(new Rect(1280,720,1,1));cmd.DrawProcedural(Matrix4x4.identity,mat,1,MeshTopology.Triangles,6);cmd.CopyTexture(light,0,0,1280,720,1,1,pixel,0,0,0,0);Graphics.ExecuteCommandBuffer(cmd);var read=AsyncGPUReadback.Request(pixel,0,TextureFormat.RGBAFloat);read.WaitForCompletion();if(read.hasError)throw new InvalidOperationException("Motion readback failed");lastPixel=read.GetData<Color>()[0];return readNoise?lastPixel.r:lastPixel.a;}
    for(int mode=0;mode<2;mode++){if(mode==0)mat.EnableKeyword("WEATHER_POINT_NOISE");else mat.DisableKeyword("WEATHER_POINT_NOISE");var deltas=new List<float>();float sum=0;for(int location=0;location<96;location++){float previous=0;for(int sub=0;sub<4;sub++){float alpha=Draw(location*Mathf.PI*2/96+sub*.00003f);if(!float.IsFinite(alpha))throw new InvalidOperationException("Non-finite cloud opacity");sum+=alpha;if(sub>0)deltas.Add(Mathf.Abs(alpha-previous));previous=alpha;}}deltas.Sort();float p95=deltas[(int)(deltas.Count*.95)],maximum=deltas[deltas.Count-1],mean=sum/(96*4);if(mode==0){report.pointP95=p95;report.pointMaximum=maximum;report.pointMeanOpacity=mean;}else{report.filteredP95=p95;report.filteredMaximum=maximum;report.filteredMeanOpacity=mean;}}
    readNoise=true;mat.EnableKeyword("WEATHER_DIAGNOSTIC");mat.SetFloat("_WeatherDiagnosticStage",3);
    for(int mode=0;mode<2;mode++){if(mode==0)mat.EnableKeyword("WEATHER_POINT_NOISE");else mat.DisableKeyword("WEATHER_POINT_NOISE");float jump=0;for(int i=0;i<64;i++){mat.SetVector("_WeatherNoiseProbePoint",new Vector3(i*.731f+3.17f,i*.117f+1.93f,i*.357f+5.13f));mat.SetFloat("_WeatherDetailNoiseLod",.99999f);float a=Draw(0);mat.SetFloat("_WeatherDetailNoiseLod",1.00001f);float b=Draw(0);jump=Mathf.Max(jump,Mathf.Abs(a-b));}if(mode==0)report.pointLodJump=jump;else report.filteredLodJump=jump;}
    readNoise=false;mat.SetFloat("_WeatherDiagnosticStage",4);mat.SetFloat("_WeatherDetailNoiseLod",0);
    for(int mode=0;mode<2;mode++){if(mode==0)mat.EnableKeyword("WEATHER_POINT_NOISE");else mat.DisableKeyword("WEATHER_POINT_NOISE");float maximum=0;for(int physical=0;physical<2;physical++){mat.SetVector("_AirScattering",new Vector4(physical,0,1,1));for(int i=0;i<32;i++){mat.SetFloat("_WeatherDiagnosticCloudAlpha",0);Draw(i*Mathf.PI*2/32);Color a=lastPixel;mat.SetFloat("_WeatherDiagnosticCloudAlpha",.000001f);Draw(i*Mathf.PI*2/32);Color b=lastPixel;maximum=Mathf.Max(maximum,Mathf.Abs(a.r-b.r),Mathf.Abs(a.g-b.g),Mathf.Abs(a.b-b.b),Mathf.Abs(a.a-b.a));}}if(mode==0)report.pointCloudLimitJump=maximum;else report.filteredCloudLimitJump=maximum;}
    if(report.filteredCloudLimitJump>.001f){report.status="FAIL";report.error="An effectively invisible cloud changed the atmosphere";}
    if(report.filteredLodJump>.001f){report.status="FAIL";report.error="Mip transition changed the cloud noise phase";}
    if(report.filteredP95>report.pointP95*.75f||Math.Abs(report.filteredMeanOpacity-report.pointMeanOpacity)>report.pointMeanOpacity*.2f){report.status="FAIL";report.error="Filtering did not sufficiently stabilize motion while retaining average opacity";}
    if(ShaderUtil.ShaderHasError(mat.shader)){report.status="FAIL";report.error="Weather shader compile error";}
   }catch(Exception e){report.status="FAIL";report.error=e.ToString();UnityEngine.Debug.LogException(e);}finally{cmd?.Dispose();if(mat!=null)Object.DestroyImmediate(mat);if(noise!=null)Object.DestroyImmediate(noise);if(depth!=null)Object.DestroyImmediate(depth);foreach(var r in new[]{light,trans,pixel})if(r!=null){r.Release();Object.DestroyImmediate(r);}Directory.CreateDirectory("TestResults/Planetary/WeatherMotion");File.WriteAllText("TestResults/Planetary/WeatherMotion/result.json",JsonUtility.ToJson(report,true));UnityEngine.Debug.Log("Weather motion validation: "+report.status);}
  }
 }
}
